    for (let d = 8; d < Ll - 2; d += 12){ const px = F0[0] - nx*d, pz = F0[2] - nz*d; cylV(M.v, 0.35, 0.4, GY(px, pz) - 0.4, gR + yL - 0.3, px, pz, 6); }
