  line([P(2.5, 0), P(Lc, 0)], 0.45, '#e6bd3a');
  for (const sd of [-1, 1]){ const pts = [P(Lc, 0)]; for (let k = 1; k <= 8; k++){ const th = k/8*PI/2; pts.push(P(Lc + Math.sin(th)*Rr, sd*(1 - Math.cos(th))*Rr)); }
    pts.push(P(Lc + Rr, sd*Math.max(Rr + 1, Ac.W/2 + 2.5))); line(pts, 0.45, '#e6bd3a'); }
  // stop bars for the nose wheel (one per aircraft size) and the lead-in 'T'
  const sw = code === 'C' ? 4.5 : 6.0, sb = code === 'C' ? 4.2 : code === 'E' ? 6.2 : 7.2;
  line([P(sb, -sw/2), P(sb, sw/2)], 0.9, '#e6bd3a');
  line([P(sb + 9, -2), P(sb + 9, 2)], 0.6, '#e6bd3a');
  if (!nb) return;
  // red equipment restraint lines along both sides of the stand and the head-of-stand line
  const half = Ac.W/2 + 2.2, front = -9;
  line([P(front, -half), P(Ac.L*0.45, -half)], 0.3, '#c8463a');
  line([P(front, half), P(Ac.L*0.45, half)], 0.3, '#c8463a');
  line([P(-1.5, -half), P(-1.5, half)], 0.3, '#c8463a');
  // white safety line round the bridge working area
